import { PrismaClient } from "../app/generated/prisma";

const prisma = new PrismaClient();

export interface ListPayoutArgs {
  status_id?: number;
  take?: number;
}

export async function listPayout(args: ListPayoutArgs) {
  return prisma.payout.findMany({
      where: args.status_id ? { status_id: { equals: args.status_id } } : undefined,
      orderBy: { releasedAt: "desc" },
      take: args.take ?? 50,
  });
}

